import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectBookingModal from "../components/RejectBookingModal";
import Sidebar from "../components/Sidebar";
import api from "../services/api";

const adminNavItems = [
  { key: "pending", label: "Pending", icon: "P" },
  { key: "schedule", label: "Schedule", icon: "S" },
  { key: "history", label: "History", icon: "H" },
  { key: "incharges", label: "Incharges", icon: "I" }
];

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [activeItem, setActiveItem] = useState("pending");
  const [pendingBookings, setPendingBookings] = useState([]);
  const [schedule, setSchedule] = useState([]);
  const [history, setHistory] = useState([]);
  const [inchargeGroups, setInchargeGroups] = useState([]);
  const [showIncharges, setShowIncharges] = useState(false);
  const [rejectBooking, setRejectBooking] = useState(null);
  const [rejectReason, setRejectReason] = useState("");
  const [rejectLoading, setRejectLoading] = useState(false);
  const [message, setMessage] = useState("");

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const loadData = async () => {
    try {
      const [pendingResponse, scheduleResponse, historyResponse, inchargesResponse] = await Promise.all([
        api.get("/admin/bookings/pending"),
        api.get("/admin/schedule"),
        api.get("/admin/history"),
        api.get("/incharges")
      ]);

      setPendingBookings(pendingResponse.data || []);
      setSchedule(scheduleResponse.data || []);
      setHistory(historyResponse.data || []);
      setInchargeGroups(inchargesResponse.data || []);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load dashboard data.");
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleApprove = async (bookingId) => {
    try {
      await api.post(`/admin/bookings/${bookingId}/approve`);
      setMessage("Booking approved.");
      await loadData();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Approval failed.");
    }
  };

  const openRejectModal = (booking) => {
    setRejectBooking(booking);
    setRejectReason("");
  };

  const closeRejectModal = () => {
    setRejectBooking(null);
    setRejectReason("");
    setRejectLoading(false);
  };

  const handleRejectSubmit = async () => {
    if (!rejectBooking || !rejectReason.trim()) {
      return;
    }

    setRejectLoading(true);
    try {
      await api.post(`/admin/bookings/${rejectBooking.id}/reject`, {
        reason: rejectReason.trim()
      });
      setMessage("Booking rejected.");
      closeRejectModal();
      await loadData();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Rejection failed.");
      setRejectLoading(false);
    }
  };

  const handleSidebarSelect = (itemKey) => {
    if (itemKey === "incharges") {
      setShowIncharges(true);
      return;
    }

    setShowIncharges(false);
    setActiveItem(itemKey);
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Admin"
        items={adminNavItems}
        activeItem={showIncharges ? "incharges" : activeItem}
        onSelect={handleSidebarSelect}
        onLogout={handleLogout}
      />

      <main className="dashboard-main">
        <Navbar
          title="Admin Control Panel"
          subtitle="Review pending requests, track schedules, and manage rejection reasons."
          userRole="Admin"
        />

        {message ? <div className="alert info">{message}</div> : null}

        <section className="summary-grid">
          <div className="metric-card metric-card-pending">
            <p>Pending Requests</p>
            <h2>{pendingBookings.length}</h2>
          </div>
          <div className="metric-card metric-card-approved">
            <p>Total Schedule Items</p>
            <h2>{schedule.length}</h2>
          </div>
          <div className="metric-card metric-card-rejected">
            <p>Processed History</p>
            <h2>{history.length}</h2>
          </div>
        </section>

        {activeItem === "pending" ? (
          <BookingList
            title="Pending Bookings"
            description="Only bookings from your assigned block appear here."
            bookings={pendingBookings}
            onApprove={handleApprove}
            onReject={openRejectModal}
            showActions
            adminMode
          />
        ) : null}

        {activeItem === "schedule" ? (
          <BookingList
            title="Current Schedule"
            description="Full booking schedule for your block."
            bookings={schedule}
          />
        ) : null}

        {activeItem === "history" ? (
          <BookingList
            title="Booking History"
            description="Approved, rejected, and cancelled records for your block."
            bookings={history}
          />
        ) : null}
      </main>

      <InchargeModal open={showIncharges} groups={inchargeGroups} onClose={() => setShowIncharges(false)} />
      <RejectBookingModal
        booking={rejectBooking}
        reason={rejectReason}
        loading={rejectLoading}
        onReasonChange={setRejectReason}
        onClose={closeRejectModal}
        onSubmit={handleRejectSubmit}
      />
    </div>
  );
};

export default AdminDashboard;
